import { useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { Input, Tag } from '@jinx-ui/react';

export type TagPickerProps = {
  initialTags?: string[];
  label?: string;
  placeholder?: string;
  onChange?: (tags: string[]) => void;
};

export default function TagPicker({
  initialTags = [],
  label = 'Теги',
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commit = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const name = draft.trim();
    if (!name) return;
    setDraft('');
    if (tags.some((tag) => tag.toLowerCase() === name.toLowerCase())) return;
    commit([...tags, name]);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      commit(tags.slice(0, -1));
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
      <Input
        label={label}
        value={draft}
        placeholder={placeholder}
        onChange={(event: ChangeEvent<HTMLInputElement>) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={addTag}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-1)' }}>
          {tags.map((tag) => (
            <Tag key={tag} onRemove={() => commit(tags.filter((item) => item !== tag))}>
              {tag}
            </Tag>
          ))}
        </div>
      )}
    </div>
  );
}

